using PrincesPalace.Domain.Content;
using UnityEngine;

namespace PrincesPalace.Content
{
    // One realms.json row, generated by ContentBuilder and never hand-edited.
    // The fields live in ResolvedRealm; this asset stores it.
    public class RealmDefinition : ScriptableObject, IOrderedContent
    {
        [SerializeField] private ResolvedRealm data = new ResolvedRealm();

        public ResolvedRealm Data => data;

        // Editor-only, and the only assignment to `data` anywhere.
        internal void SetData(ResolvedRealm value) => data = value ?? new ResolvedRealm();

        // By floor, the row's only key.
        public int SortOrder => data != null ? data.Floor : 0;
    }
}
